def foldfix(g):
    out=g.copy(); nconf=0
    for r in range(16):
        for c in range(16):
            vals=[g[r,c],g[15-r,c],g[r,15-c],g[15-r,15-c]]
            if len(set(vals))>1:
                nconf+=1
                out[r,c]=collections.Counter(vals).most_common(1)[0][0]
    return out,nconf
